// The audio director: owns every expo-audio player, follows the game store, and turns bus events into sound.
// Rules live in logic.ts (tested); cue data in manifest.ts (generated by tools/audio/build.py); docs in docs/AUDIO.md.
import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import { AppState, Platform } from 'react-native';

import { HOME_SCENES } from '../content/scenes/home';
import type { NeighborhoodId, PanelCue } from '../content/types';
import { useGame } from '../store/game-store';
import { onAudio, type AudioEvent } from './bus';
import {
  DUCK, EXCLUSIVE_CUES, PurchaseChain, RESTART_TRACKS, StingGate, VoiceLimiter, beatUnit, musicFor, nextVariant, panelCue, quantizeDelay, sharedTimeline,
  stingDuck, stingTiming, stingUnit, type MusicTrack, type StingKind,
} from './logic';
import { MUSIC, SFX, STINGS, STORY, type SfxId, type StoryCueId } from './manifest';
import { useAudioPrefs } from './prefs';

const CROSSFADE_MS = 600; // AU19
const DUCK_DOWN_MS = 80; // AU22
const DUCK_UP_MS = 400;
const SKIP_FADE_MS = 400;
const CUE_OUT_MS = 300; // an outgoing story cue always fades (AU26)
const STING_OUT_MS = 150; // a scene's first panel clears gameplay stingers (AU27)
const SFX_UNDER_STING = 0.7; // AU38
/** Most-heard effects are created at start-up; the rest on first use, then kept (never per tap). */
const PRELOAD: SfxId[] = ['tap', 'cash', 'buy', 'rush', 'bubble', 'full', 'refused', 'click'];
/** Rare one-shots: their player is released after each play instead of staying resident (AU55). */
const RARE: ReadonlySet<SfxId> = new Set(['collect', 'build', 'gavel', 'grade', 'expand']);
const STING_PRELOAD: StingKind[] = ['bottleneck', 'milestone', 'milestone_big', 'manager', 'upgrade', 'fleet', 'drone', 'build', 'perk'];
const SCENES = new Map(HOME_SCENES.map((s) => [s.id, s]));

// ------------------------------------------------------------------------------------------------ volume ramps
interface Ramp { p: AudioPlayer; from: number; to: number; t0: number; ms: number; done?: () => void }
const ramps = new Map<AudioPlayer, Ramp>();
let rampTimer: ReturnType<typeof setInterval> | null = null;

function rampTo(p: AudioPlayer, to: number, ms: number, done?: () => void) {
  const from = safe(() => p.volume, to);
  if (ms <= 0 || Math.abs(from - to) < 0.002) {
    safe(() => (p.volume = to));
    ramps.delete(p);
    done?.();
    return;
  }
  ramps.set(p, { p, from, to, t0: Date.now(), ms, done });
  if (!rampTimer) rampTimer = setInterval(stepRamps, 30);
}

function stepRamps() {
  const now = Date.now();
  for (const r of [...ramps.values()]) {
    const k = Math.min(1, (now - r.t0) / r.ms);
    safe(() => (r.p.volume = r.from + (r.to - r.from) * k));
    if (k >= 1) {
      ramps.delete(r.p);
      r.done?.();
    }
  }
  if (ramps.size === 0 && rampTimer) {
    clearInterval(rampTimer);
    rampTimer = null;
  }
}

function safe<T>(f: () => T, fallback?: T): T {
  try {
    return f();
  } catch {
    return fallback as T;
  }
}

function make(src: number | null): AudioPlayer {
  const p = createAudioPlayer(src);
  safe(() => (p.shouldCorrectPitch = false));
  return p;
}

/**
 * Start a one-shot from the top. A player that has played is rewound right after it ends, so the next play()
 * is immediate; one still mid-sound is seeked first and played when the seek lands (AU39).
 */
function fire(p: AudioPlayer, seconds: number, volume: number, rate = 1, onEnd?: () => void) {
  ramps.delete(p);
  safe(() => {
    p.volume = volume;
    if (rate !== 1) p.setPlaybackRate(rate);
    else if (safe(() => p.playbackRate, 1) !== 1) p.setPlaybackRate(1);
  });
  const at = safe(() => p.currentTime, 0);
  if (at > 0.01) {
    void p.seekTo(0).then(() => safe(() => p.play())).catch(() => {});
  } else safe(() => p.play());
  setTimeout(() => {
    if (onEnd) return onEnd();
    if (!safe(() => p.playing, false)) void p.seekTo(0).catch(() => {});
  }, (seconds / rate) * 1000 + 60);
}

// ------------------------------------------------------------------------------------------------ state
let started = false;
let unlocked = Platform.OS !== 'web'; // web: browsers block audio until the first gesture
let appActive = true;

// music: two players for crossfades (AU23: at most 2)
const deck: AudioPlayer[] = [];
let front = 0;
let current: MusicTrack | null = null;
const positions = new Map<MusicTrack, number>();
/** Multiplicative ducks keyed by reason; the loop plays at the product. */
const ducks = new Map<string, number>();
const duckTimers = new Map<string, ReturnType<typeof setTimeout>>();

// effects
const sfxPlayers = new Map<string, AudioPlayer>();
const lastVariant = new Map<SfxId, number>();
const popLimiter = new VoiceLimiter();
const rushLimiter = new VoiceLimiter();
const chain = new PurchaseChain();
const gate = new StingGate();

// stingers: only the active key's are kept (AU23), preloaded shortly after a key change (AU40)
let stingHood: NeighborhoodId | null = null;
const stingPlayers = new Map<string, AudioPlayer>();
const pendingStings = new Set<ReturnType<typeof setTimeout>>();
let preloadTimer: ReturnType<typeof setTimeout> | null = null;

/** Build and bid stingers carry into the scene they open; story cues wait for them (AU42). */
let heldUntil = 0;
let heldKind: 'build' | 'bid' | null = null;
const pendingCues = new Set<ReturnType<typeof setTimeout>>();

// story: two players, so an outgoing cue fades while the next starts (AU26)
const story: AudioPlayer[] = [];
let storyFront = 0;
let storyEnd: ReturnType<typeof setTimeout> | null = null;
/** The story cue on the front player: for payoff protection (AU45), the perk's bar grid (AU46) and resume (AU54). */
let storyNow: { id: StoryCueId; startedAt: number; pausedAt: number | null; exclusive: boolean } | null = null;
let scenePanelCue: PanelCue = 'none';
let lastScenePanel = '';

// ------------------------------------------------------------------------------------------------ music
function musicGain() {
  if (!useAudioPrefs.getState().music || !appActive || !unlocked) return 0;
  let g = 1;
  for (const d of ducks.values()) g *= d;
  return g;
}

function applyMusicVolume(ms: number) {
  const p = deck[front];
  if (!p || !current) return;
  const g = musicGain();
  if (g > 0) {
    if (!safe(() => p.playing, false)) safe(() => p.play());
    rampTo(p, g, ms);
  } else {
    // silent: pause rather than decode at volume 0 (resumes from the same spot)
    rampTo(p, 0, ms, () => {
      if (musicGain() === 0) safe(() => p.pause());
    });
  }
}

function setDuck(reason: string, gain: number | null, holdMs?: number) {
  const t = duckTimers.get(reason);
  if (t) clearTimeout(t);
  duckTimers.delete(reason);
  const before = musicGain();
  if (gain === null) ducks.delete(reason);
  else ducks.set(reason, gain);
  applyMusicVolume(musicGain() < before ? DUCK_DOWN_MS : DUCK_UP_MS);
  if (gain !== null && holdMs) {
    duckTimers.set(reason, setTimeout(() => setDuck(reason, null), holdMs));
  }
}

function switchMusic(next: MusicTrack) {
  if (next === current) return;
  const out = deck[front];
  const outPos = out && current ? safe(() => out.currentTime, 0) : 0;
  if (current && out) {
    positions.set(current, outPos);
    rampTo(out, 0, CROSSFADE_MS, () => safe(() => out.pause()));
  }
  // Nonna's takeover: the full band picks up where the sparse chart was (AU41)
  if (sharedTimeline(current, next)) positions.set(next, outPos);
  if (RESTART_TRACKS.has(next)) positions.set(next, 0);
  front = 1 - front;
  const inc = deck[front];
  current = next;
  const info = MUSIC[next];
  safe(() => inc.replace(info.src));
  safe(() => (inc.loop = true));
  safe(() => (inc.volume = 0));
  const pos = (positions.get(next) ?? 0) % info.seconds;
  if (pos > 0) void inc.seekTo(pos).catch(() => {});
  if (musicGain() > 0) safe(() => inc.play());
  rampTo(inc, musicGain(), CROSSFADE_MS);
}

function refreshMusic() {
  const s = useGame.getState();
  if (!s.loaded) return; // no Downtown blip before the save says where the player is (AU44)
  const scene = s.playing ? s.playing.scene : null;
  const track = musicFor({
    active: s.game.active,
    downtownFull: s.game.seenScenes.includes('downtown-4'),
    scene: scene ? { neighborhood: scene.neighborhood, panelCue: scenePanelCue, beat: scene.beat } : null,
  });
  switchMusic(track);
  setDuck('scene', scene ? DUCK.scene : null);
  setDuck('popup', s.offline && !scene ? DUCK.popup : null);
  // a scene's stingers are in its own key; preload there while it plays (AU43)
  scheduleStingPreload(scene ? scene.neighborhood : s.game.active);
}

// ------------------------------------------------------------------------------------------------ effects
function sfxPlayer(id: SfxId, v: number) {
  const key = `${id}/${v}`;
  let p = sfxPlayers.get(key);
  if (!p) {
    p = make(SFX[id][v] as number);
    sfxPlayers.set(key, p);
  }
  return p;
}

const SFX_SECONDS: Partial<Record<SfxId, number>> = { collect: 1.5, build: 0.8, fleet: 0.6, grade: 0.6, gavel: 0.6, expand: 0.5, milestone: 0.4 };

function playSfx(id: SfxId, opts: { variant?: number; gain?: number; jitter?: number } = {}) {
  if (!useAudioPrefs.getState().sound || !unlocked || !appActive) return;
  const n = SFX[id].length;
  const v = Math.min(n - 1, opts.variant ?? nextVariant(lastVariant.get(id) ?? -1, n, Math.random()));
  lastVariant.set(id, v);
  const semis = (Math.random() * 2 - 1) * (opts.jitter ?? 1);
  const under = gate.busy(Date.now()) ? SFX_UNDER_STING : 1;
  const key = `${id}/${v}`;
  const p = sfxPlayer(id, v);
  const release = RARE.has(id)
    ? () => {
        if (sfxPlayers.get(key) !== p) return;
        sfxPlayers.delete(key);
        safe(() => p.remove());
      }
    : undefined;
  fire(p, SFX_SECONDS[id] ?? 0.35, (opts.gain ?? 1) * under, Math.pow(2, semis / 12), release);
}

// ------------------------------------------------------------------------------------------------ stingers
function useStingKey(hood: NeighborhoodId) {
  if (stingHood === hood) return;
  for (const p of stingPlayers.values()) {
    // a stinger still sounding is released when it ends, never cut (AU43)
    if (safe(() => p.playing, false)) {
      const left = Math.max(0, safe(() => p.duration - p.currentTime, 0));
      setTimeout(() => safe(() => p.remove()), left * 1000 + 200);
    } else safe(() => p.remove());
  }
  stingPlayers.clear();
  stingHood = hood;
}

function stingPlayer(hood: NeighborhoodId, kind: StingKind | 'bid') {
  if (kind !== 'build' && kind !== 'bid') useStingKey(hood);
  const key = `${hood}_${kind}` as keyof typeof STINGS;
  let p = stingPlayers.get(key);
  if (!p) {
    p = make(STINGS[key].src);
    // other keys' build/bid players are kept with the active key's set and released with it
    stingPlayers.set(key, p);
  }
  return { p, info: STINGS[key] };
}

function scheduleStingPreload(hood: NeighborhoodId) {
  if (stingHood === hood) return;
  if (preloadTimer) clearTimeout(preloadTimer);
  preloadTimer = setTimeout(() => {
    preloadTimer = null;
    const st = useGame.getState();
    const h = st.playing ? st.playing.scene.neighborhood : st.game.active;
    if (!useAudioPrefs.getState().music) return;
    for (const k of STING_PRELOAD) safe(() => stingPlayer(h, k));
  }, 1500);
}

/** Fade gameplay stingers out. `keepHeld`: a build or bid stinger rides into the scene it opened (AU42). */
function stopStings(ms: number, keepHeld = false) {
  for (const t of pendingStings) clearTimeout(t);
  pendingStings.clear();
  const held = keepHeld && heldKind && Date.now() < heldUntil ? heldKind : null;
  for (const [key, p] of stingPlayers) {
    if (held && key.endsWith(`_${held}`)) continue;
    if (safe(() => p.playing, false)) rampTo(p, 0, ms, () => safe(() => p.pause()));
  }
  gate.clear();
  if (!held) {
    setDuck('sting', null);
    heldUntil = 0;
    heldKind = null;
  }
}

/** Run a story cue now, or when the held build/bid stinger ends — unless the scene has moved on by then (AU57). */
function afterHeld(fn: () => void) {
  const wait = heldUntil - Date.now();
  if (wait <= 0) return fn();
  const panelAtCall = lastScenePanel;
  const t = setTimeout(() => {
    pendingCues.delete(t);
    if (lastScenePanel === panelAtCall) fn();
  }, wait);
  pendingCues.add(t);
}

function clearPendingCues() {
  for (const t of pendingCues) clearTimeout(t);
  pendingCues.clear();
}

/** Play a stinger in `hood`'s key; its beat 1 lands on the loop's next beat or bar unless `immediate`. */
function playSting(hood: NeighborhoodId, kind: StingKind | 'bid', o: { immediate?: boolean; gated?: boolean; duck?: number } = {}) {
  if (!useAudioPrefs.getState().music || !unlocked || !appActive) return;
  const { p, info } = stingPlayer(hood, kind);
  const now = Date.now();
  const m = current ? MUSIC[current] : null;
  const pos = m && deck[front] ? safe(() => deck[front].currentTime, NaN) : NaN;
  // chordal stingers wait for a bar on the tonic (AU47); the bottleneck line only for the next beat
  let delay = 0;
  let extra = 1;
  if (!o.immediate && m && Number.isFinite(pos) && kind !== 'bid') {
    const unit = stingUnit(kind as StingKind, m.beatsPerBar, current!);
    if (unit === beatUnit(current!)) delay = quantizeDelay(pos, m.bpm, unit, info.downbeatSeconds);
    else {
      const roots = 'barRoots' in m ? (m.barRoots as readonly number[]) : undefined;
      ({ delay, extraDuck: extra } = stingTiming(pos, m.bpm, m.beatsPerBar, roots, info.downbeatSeconds));
    }
  }
  // the duck and the gate last as long as the music, not the reverb tail (AU53)
  const musicLen = (info as { musicSeconds?: number; seconds: number }).musicSeconds ?? info.seconds;
  if (o.gated !== false && kind !== 'bid' && !gate.admit(kind as StingKind, now, (delay + musicLen) * 1000)) return;
  if (kind === 'build' || kind === 'bid') {
    heldKind = kind;
    heldUntil = now + musicLen * 1000;
  }
  const t = setTimeout(() => {
    pendingStings.delete(t);
    setDuck('sting', (o.duck ?? (kind === 'bid' ? DUCK.bid : stingDuck(kind as StingKind))) * extra, musicLen * 1000);
    fire(p, info.seconds, 1);
  }, delay * 1000);
  pendingStings.add(t);
}

// ------------------------------------------------------------------------------------------------ story
function playStory(id: StoryCueId, exclusive: boolean) {
  // a triumph is never cut before its payoff crash plus a beat (AU45)
  const out = storyNow ? STORY[storyNow.id] : null;
  if (out && storyNow && 'payoffSeconds' in out && storyNow.pausedAt === null) {
    const beat = 'bpm' in out ? 60 / (out.bpm as number) : 0.5;
    const wait = storyNow.startedAt + ((out.payoffSeconds as number) + beat) * 1000 - Date.now();
    if (wait > 0) {
      const t = setTimeout(() => {
        pendingCues.delete(t);
        playStory(id, exclusive);
      }, wait);
      pendingCues.add(t);
      return;
    }
  }
  stopStory(CUE_OUT_MS, exclusive);
  if (!useAudioPrefs.getState().music || !unlocked || !appActive) return;
  storyFront = 1 - storyFront;
  const p = story[storyFront];
  if (!p) return;
  const info = STORY[id];
  ramps.delete(p);
  safe(() => {
    p.replace(info.src);
    p.volume = 1;
    p.play();
  });
  if (exclusive) setDuck('story', 0);
  storyNow = { id, startedAt: Date.now(), pausedAt: null, exclusive };
  armStoryEnd(info.seconds * 1000);
}

function armStoryEnd(ms: number) {
  if (storyEnd) clearTimeout(storyEnd);
  storyEnd = setTimeout(() => {
    storyEnd = null;
    storyNow = null;
    setDuck('story', null);
  }, ms);
}

function stopStory(ms: number, keepDuck = false) {
  if (storyEnd) clearTimeout(storyEnd);
  storyEnd = null;
  storyNow = null;
  const p = story[storyFront];
  if (p && safe(() => p.playing, false)) rampTo(p, 0, ms, () => safe(() => p.pause()));
  if (!keepDuck) setDuck('story', null);
}

function onPanel(sceneId: string, panel: number) {
  const scene = SCENES.get(sceneId);
  if (!scene) return;
  const key = `${sceneId}/${panel}`;
  if (key === lastScenePanel) return;
  lastScenePanel = key;
  // a cue still waiting for the previous panel (held stinger, triumph payoff) belongs to that panel: drop it (AU57)
  clearPendingCues();
  // a scene never opens over a gameplay stinger (AU27), except the build or bid stinger that opened it (AU42)
  if (panel === 0) stopStings(STING_OUT_MS, true);
  const cue = panelCue(scene, panel);
  scenePanelCue = cue;
  refreshMusic();
  const hood = scene.neighborhood;
  switch (cue) {
    case 'welcome':
    case 'warmth':
      return afterHeld(() => playSting(hood, cue, { gated: false }));
    case 'rep':
      // Dock Saved: the D-minor version over an A pedal keeps the bid's A7 hanging for the bell triumph (AU42)
      return afterHeld(() => playStory(scene.trigger.kind === 'bid' ? 'megaslice_rep_dock' : 'megaslice_rep', EXCLUSIVE_CUES.has('rep')));
    case 'victor-exit':
      return playStory('victor_exit', false);
    case 'triumph':
      return playStory(`triumph_${hood}` as StoryCueId, true);
    case 'bell-triumph':
      return playStory('triumph_waterfront', true);
    case 'recipe':
      return playStory('recipe', true);
    case 'reunion':
      return playStory('reunion', true);
    case 'city-theme':
      return playStory('city_theme', true);
    default:
      return;
  }
}

// ------------------------------------------------------------------------------------------------ events
function handle(e: AudioEvent) {
  const g = useGame.getState();
  const active = g.game.active;
  const sceneHood = g.playing?.scene.neighborhood ?? active;
  const now = Date.now();
  switch (e.type) {
    case 'tap':
      return playSfx('tap');
    case 'full':
      return playSfx('full', { jitter: 0.5 });
    case 'rush': {
      const gain = rushLimiter.hit(now);
      return gain > 0 ? playSfx('rush', { gain }) : undefined;
    }
    case 'cash': {
      const gain = popLimiter.hit(now);
      return gain > 0 ? playSfx('cash', { gain, jitter: 2 }) : undefined;
    }
    case 'refused':
      return playSfx('refused', { jitter: 0.5 });
    case 'click':
      return playSfx('click', { jitter: 0.3 });
    case 'bubble':
      return playSfx('bubble', { jitter: 0.5 });
    case 'buy': {
      if (e.what === 'expand') playSfx('expand', { jitter: 0.5 });
      else if (e.what === 'grade') playSfx('grade', { jitter: 0.5 });
      else if (e.what === 'fleet') playSfx('fleet', { variant: e.vehicle ?? 0, jitter: 0 });
      else if (e.what === 'build') playSfx('build', { jitter: 0 });
      else if (e.what === 'bid') playSfx('gavel', { jitter: 0 });
      else {
        const step = chain.next(now);
        playSfx('buy', { variant: step, jitter: step === 0 ? 0.3 : 0 }); // AU37: slow play still varies
      }
      if (e.what === 'decor') playSfx('sparkle', { jitter: 0.5 });
      if (e.sting === 'milestone' || e.sting === 'milestone_big') playSfx('milestone', { jitter: 0 });
      // the bid holds a tension chord the Dock Saved scene resolves; a new pizzeria plays its own neighbourhood's motif
      if (e.what === 'bid') return playSting('waterfront', 'bid', { immediate: true });
      if (e.what === 'build' && e.hood) return playSting(e.hood, 'build', { immediate: true });
      if (e.sting) playSting(active, e.sting);
      return;
    }
    case 'perk': {
      // layered over a triumph or the city theme still ringing, in the scene's key (AU26): it waits for the cue's
      // payoff, so it never plays against a tempo grid other than its own (AU66; the cues keep their old tempos)
      const cue = storyNow && storyNow.pausedAt === null ? STORY[storyNow.id] : null;
      if (cue && 'payoffSeconds' in cue && storyNow) {
        const wait = (cue.payoffSeconds as number) - (now - storyNow.startedAt) / 1000;
        if (wait > 0 && wait < 3) {
          const t = setTimeout(() => {
            pendingCues.delete(t);
            playSting(sceneHood, 'perk', { immediate: true, gated: false, duck: 1 });
          }, wait * 1000);
          pendingCues.add(t);
          return;
        }
      }
      return playSting(sceneHood, 'perk', { immediate: true, gated: false, duck: 1 });
    }
    case 'offline-open':
      return; // played from the store subscription once the save is loaded (AU44)
    case 'collect':
      return playSfx('collect', { variant: e.size, jitter: 0 });
    case 'scene-panel':
      return onPanel(e.sceneId, e.panel);
    case 'scene-skip':
      clearPendingCues();
      stopStings(SKIP_FADE_MS);
      return stopStory(SKIP_FADE_MS);
  }
}

/** Start the director once, at app start (root layout). Safe to call again. */
export function startAudio() {
  if (started) return;
  started = true;
  // AU24: obey the silent switch, mix with the player's own music or podcast, stop in the background
  void setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers', shouldPlayInBackground: false }).catch(() => {});
  void useAudioPrefs.getState().load();
  safe(() => {
    deck.push(make(null), make(null));
    story.push(make(null), make(null));
    for (const id of PRELOAD) for (let v = 0; v < SFX[id].length; v++) sfxPlayer(id, v);
  });
  onAudio(handle);

  if (Platform.OS === 'web' && typeof document !== 'undefined') {
    const unlock = () => {
      unlocked = true;
      document.removeEventListener('pointerdown', unlock);
      refreshMusic();
    };
    document.addEventListener('pointerdown', unlock);
  }

  let lastPlaying = useGame.getState().playing;
  let lastActive = useGame.getState().game.active;
  let lastSeen = useGame.getState().game.seenScenes.length;
  let lastOffline = useGame.getState().offline;
  let lastLoaded = useGame.getState().loaded;
  useGame.subscribe((s) => {
    if (s.playing !== lastPlaying) {
      if (!s.playing) {
        scenePanelCue = 'none';
        lastScenePanel = '';
        clearPendingCues();
        stopStory(SKIP_FADE_MS);
      }
      lastPlaying = s.playing;
      refreshMusic();
    }
    if (s.loaded !== lastLoaded) {
      lastLoaded = s.loaded;
      refreshMusic();
    }
    if (s.game.active !== lastActive || s.game.seenScenes.length !== lastSeen || s.offline !== lastOffline) {
      // the popup's celesta in the saved neighbourhood's key, once the save is in (AU44)
      if (s.offline && !lastOffline && s.loaded) playSting(s.game.active, 'offline', { immediate: true, gated: false, duck: 1 });
      lastActive = s.game.active;
      lastSeen = s.game.seenScenes.length;
      lastOffline = s.offline;
      refreshMusic();
    }
  });
  useAudioPrefs.subscribe((p) => {
    if (!p.music) {
      clearPendingCues();
      stopStory(200);
      stopStings(200);
    }
    refreshMusic();
  });
  // Control Center or a notification makes the app `inactive`, not backgrounded: keep playing (AU54)
  AppState.addEventListener('change', (state) => {
    const was = appActive;
    appActive = state !== 'background';
    if (was === appActive) return;
    if (!appActive) {
      safe(() => deck[front]?.pause());
      for (const p of story) safe(() => p.pause());
      if (storyNow) {
        storyNow.pausedAt = Date.now();
        if (storyEnd) clearTimeout(storyEnd);
        storyEnd = null;
      }
      stopStings(0);
    } else {
      // resume a story cue with more than half a second left, else let the loop back in
      const cue = storyNow;
      if (cue && cue.pausedAt !== null) {
        const played = (cue.pausedAt - cue.startedAt) / 1000;
        const left = STORY[cue.id].seconds - played;
        if (left > 0.5 && useAudioPrefs.getState().music) {
          cue.startedAt = Date.now() - played * 1000;
          cue.pausedAt = null;
          safe(() => story[storyFront].play());
          armStoryEnd(left * 1000);
        } else stopStory(0);
      }
      refreshMusic();
    }
  });
  refreshMusic();
}
